import {
  Object3D,
  Mesh,
  PlaneGeometry,
  CylinderGeometry,
  Color,
  Texture,
  Vector2,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  color,
  mix,
  uv,
  texture,
  float,
  add,
  sub,
  mul,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {any} colors
 * @property {any} typography
 * @property {any} visual
 * @property {any[]} textContent
 *
 * @typedef {Object} NodeContext
 * @property {{ textureLoader: { load: (url: string) => Texture }}} textureLoader
 * @property {{ fontAtlas: Texture }} fontAtlas
 * @property {{ primitives: Record<string, Function> }} primitives
 */

/**
 * Creates a feature‑triptych node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // ---------------------------------------------------------------------------
  // Constants from the specification
  // ---------------------------------------------------------------------------
  const CARD_WIDTH = 1.5;
  const CARD_HEIGHT = 1.9;
  const GAP = 0.25;
  const TOTAL_WIDTH = 5.0; // (3 * CARD_WIDTH) + (2 * GAP)

  const CARD_RADIUS = 0.06;
  const BORDER_WIDTH = 0.006;
  const BORDER_COLOR = '#26262f';

  const GRAD_TOP = '#191921';
  const GRAD_BOTTOM = '#121218';

  const DISC_DIAMETER = 0.4;
  const DISC_THICKNESS = 0.05;
  const DISC_COLOR = '#ff2a38';
  const DISC_EMISSIVE_BASE = 1.6;
  const DISC_EMISSIVE_HOVER = 2.2;

  const HOVER_LIFT_Y = 0.06;
  const HOVER_LIFT_Z = 0.12;
  const HOVER_DURATION = 0.18; // seconds

  const FADE_UP_DURATION = 0.5; // seconds
  const FADE_UP_EASE = 'cubic-bezier(0.25,0.46,0.45,0.94)';
  const STAGGER = 0.08; // seconds

  // ---------------------------------------------------------------------------
  // Prepare assets
  // ---------------------------------------------------------------------------
  const cardTexture = ctx.textureLoader.load(
    config.assets?.imageUrl ?? '',
  );

  // ---------------------------------------------------------------------------
  // Root container
  // ---------------------------------------------------------------------------
  const root = new Object3D();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.userData.handlers = {};

  // ---------------------------------------------------------------------------
  // Helper to build a card material using nodes (gradient + optional texture)
  // ---------------------------------------------------------------------------
  const createCardMaterial = () => {
    const uvNode = uv();

    // vertical gradient
    const gradientNode = mix(
      color(GRAD_TOP),
      color(GRAD_BOTTOM),
      uvNode.y,
    );

    // optional texture overlay (if needed)
    const texNode = texture(cardTexture, uvNode);
    const albedoNode = mix(gradientNode, texNode, texNode.a);

    const material = new MeshStandardNodeMaterial({
      color: albedoNode,
      roughness: float(0.6),
      metalness: float(0.25),
      clearcoat: float(0.15),
      side: 2, // DoubleSide
    });

    // border simulation via alpha (simple approach)
    material.transparent = true;
    material.alphaTest = 0.01;

    return material;
  };

  // ---------------------------------------------------------------------------
  // Build each card
  // ---------------------------------------------------------------------------
  const cardData = [
    {
      glyph: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.',
    },
    {
      glyph: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.',
    },
    {
      glyph: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.',
    },
  ];

  const timelines = [];

  cardData.forEach((data, idx) => {
    // -----------------------------------------------------------------------
    // Container for card (so we can animate whole thing together)
    // -----------------------------------------------------------------------
    const cardContainer = new Object3D();
    const offsetX = -TOTAL_WIDTH / 2 + CARD_WIDTH / 2 + idx * (CARD_WIDTH + GAP);
    cardContainer.position.set(offsetX, 0, 0);
    root.add(cardContainer);

    // -----------------------------------------------------------------------
    // Card plane
    // -----------------------------------------------------------------------
    const planeGeom = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT, 1, 1);
    const plane = new Mesh(planeGeom, createCardMaterial());
    plane.userData.handlers = {};
    cardContainer.add(plane);

    // -----------------------------------------------------------------------
    // Disc (icon seat)
    // -----------------------------------------------------------------------
    const discGeom = new CylinderGeometry(
      DISC_DIAMETER / 2,
      DISC_DIAMETER / 2,
      DISC_THICKNESS,
      32,
    );
    const discMaterial = new MeshStandardNodeMaterial({
      color: color(DISC_COLOR),
      emissive: color(DISC_COLOR),
      emissiveIntensity: float(DISC_EMISSIVE_BASE),
      metalness: float(0.5),
      roughness: float(0.55),
      clearcoat: float(0.2),
      side: 2,
    });
    const disc = new Mesh(discGeom, discMaterial);
    // Position disc: top inside the card with padding
    const padding = 0.375;
    const topY = CARD_HEIGHT / 2 - padding - DISC_THICKNESS / 2;
    disc.position.set(0, topY, 0.01);
    disc.rotation.x = Math.PI / 2; // lay flat on card surface
    cardContainer.add(disc);

    // -----------------------------------------------------------------------
    // Glyph (text) – use the shared font atlas utility
    // -----------------------------------------------------------------------
    const glyphMesh = textUtils.createSdfText({
      text: data.glyph,
      fontAtlas: ctx.fontAtlas,
      color: '#ff2a38',
      size: 0.2,
      // The utility is assumed to return an Object3D ready to be added.
    });
    glyphMesh.position.set(0, topY, 0.015);
    cardContainer.add(glyphMesh);

    // -----------------------------------------------------------------------
    // Title text
    // -----------------------------------------------------------------------
    const titleMesh = textUtils.createSdfText({
      text: data.title,
      fontAtlas: ctx.fontAtlas,
      color: '#e8ecf2',
      size: 0.18,
      // Align left‑center within card
    });
    const titleY = topY - DISC_THICKNESS / 2 - 0.25 - 0.09; // approximate
    titleMesh.position.set(0, titleY, 0.015);
    cardContainer.add(titleMesh);

    // -----------------------------------------------------------------------
    // Body text
    // -----------------------------------------------------------------------
    const bodyMesh = textUtils.createSdfText({
      text: data.body,
      fontAtlas: ctx.fontAtlas,
      color: '#e8ecf2',
      size: 0.12,
    });
    const bodyY = titleY - 0.12 - 0.125;
    bodyMesh.position.set(0, bodyY, 0.015);
    cardContainer.add(bodyMesh);

    // -----------------------------------------------------------------------
    // Staggered fade‑up animation (initial state)
    // -----------------------------------------------------------------------
    plane.material.opacity = 0;
    plane.position.y = 0.2;
    const tl = gsap.timeline({ paused: true });
    tl.fromTo(
      plane.material,
      { opacity: 0 },
      {
        opacity: 1,
        duration: FADE_UP_DURATION,
        ease: FADE_UP_EASE,
      },
      0,
    );
    tl.fromTo(
      plane.position,
      { y: 0.2 },
      { y: 0, duration: FADE_UP_DURATION, ease: FADE_UP_EASE },
      0,
    );
    timelines.push(tl);
    // schedule start based on index
    tl.delay(idx * STAGGER);
    tl.play();

    // -----------------------------------------------------------------------
    // Hover interaction
    // -----------------------------------------------------------------------
    const hoverTL = gsap.timeline({ paused: true, repeat: 0 });
    hoverTL.to(
      cardContainer.position,
      {
        y: HOVER_LIFT_Y,
        z: HOVER_LIFT_Z,
        duration: HOVER_DURATION,
        ease: FADE_UP_EASE,
      },
      0,
    );
    hoverTL.to(
      discMaterial,
      {
        emissiveIntensity: DISC_EMISSIVE_HOVER,
        duration: HOVER_DURATION,
        ease: FADE_UP_EASE,
      },
      0,
    );
    timelines.push(hoverTL);

    // attach pointer events
    plane.userData.handlers.pointerenter = () => hoverTL.play();
    plane.userData.handlers.pointerleave = () => hoverTL.reverse();
  });

  // ---------------------------------------------------------------------------
  // Cleanup routine
  // ---------------------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
    if (cardTexture) cardTexture.dispose();
  };

  return root;
}
